            { id = "mago_arc_cargas", level = 2, name = "Cargas arcanas", cast = "ninguna", type = "accion", actionKind = "arcaneCharge", description = "Al lanzar un conjuro de 1er nivel o superior ganas una carga arcana (= nivel, max 5) que gastas para sumar bonus a ataque/daño o salvaciones.", effects = { { kind = "flag", flag = "arcaneCharges" } } },
            { id = "mago_arc_desplazamiento", level = 2, name = "Desplazamiento temporal", type = "informativo", description = "Después de tirar iniciativa, pero antes de que la primera criatura tome su turno, puedes intercambiar tu resultado con el resultado de otra criatura que puedas ver. Una vez que lo hagas, no puedes usar esta característica nuevamente hasta que termines un descanso largo.", uses = { max = 1, recharge = "long" }, effects = {} },
            { id = "mago_arc_brillantez", level = 6, name = "Brillantez arcana", type = "pasivo", description = "Obtienes competencia en Conocimiento Arcano si no la tienes. Bonus Competencia se duplica para cualquier prueba de habilidad que realices con ella. Además, siempre estás bajo los efectos del conjuro *entender idiomas*.", effects = {
