        { id = "fuego", name = "Fuego", desc = "Conjuros incendiarios de alto daño y combustion.", features = {
            { id = "mago_fue_truco", level = 2, name = "Truco adicional (controlar llamas)", type = "informativo", description = "Aprendes controlar llamas (u otro truco de mago); no cuenta en tu limite.", cantripSpellIds = { "controlar_llamas" }, spellGrants = { { level = 0, ids = { "controlar_llamas" } } }, effects = {} },
            { id = "mago_fue_racha", level = 2, name = "Racha de calor", type = "informativo", description = "La energía ardiente de tus conjuros se intensifica. Cuando lanzas daño para un conjuro y sacas el número más alto posible en cualquiera de los dados, elige uno de esos dados, lánzalo de nuevo y suma ese resultado al daño. Puedes usar esta característica solo una vez por turno.\n\nA nivel 10, puedes elegir cualquier cantidad de dados que hayan sacado el número más alto posible, pero solo puedes volver a tirar cada dado una vez.", effects = { { kind = "flag", flag = "heatStreak" } } },
            { id = "mago_fue_cauterizar", level = 6, name = "Cauterizar", cast = "reaccion", type = "informativo", description = "Si te reducen a 0 puntos de golpe, puedes usar tu reacción para recurrir a la energía ardiente que arde en tu interior. En lugar de ser reducido a 0 puntos de golpe, te reduces a 1 punto de golpe, y cada criatura dentro de 3 metros de ti recibe daño de fuego igual a la mitad de tu nivel de mago + Mod. Inteligencia.\n\nUna vez que uses esta característica, no podrás usarla de nuevo hasta que termines un descanso largo.", uses = { max = 1, recharge = "long" }, effects = {} },
            { id = "mago_fue_prender", icon = "spell_fire_soulburn", level = 10, name = "Prender", type = "informativo", description = "Cuando infliges daño de fuego con un conjuro usando un espacio de conjuro de hasta 5.º nivel, puedes gastar hasta 3 puntos de hechicería para potenciarlo. Por cada punto de hechicería gastado, añade un dado extra al daño infligido por el conjuro. Por ejemplo, cuando lanzas *manos ardientes* y gastas 2 puntos, agregas 2d6 adicionales al daño del conjuro. Cuando lanzas un conjuro que hace múltiples tiradas de ataque, como *rayo abrasador*, debes gastar los puntos en cada ataque individualmente.", effects = {} },
            { id = "mago_fue_combustion", icon = "spell_fire_sealoffire", level = 14, name = "Combustión", type = "informativo", description = "Puedes desatar las llamas que arden dentro de ti. Como acción, te envuelves en un torbellino de fuego. Por 1 minuto, obtienes los siguientes beneficios: - Irradias luz brillante en un radio de 9 metros y luz tenue en 9 metros adicionales. - Cualquier criatura recibe daño de fuego igual a la mitad de tu nivel de mago si te golpea con un ataque cuerpo a cuerpo. - Cualquier conjuro o efecto que crees ignora la resistencia al daño de fuego y trata la inmunidad al daño de fuego como resistencia al mismo. - Eres inmune al daño de fuego y tienes resistencia al daño por frío. - Tus ataques de conjuro obtienen un golpe crítico con una tirada de 19 o 20 en el d20. Una vez que uses esta característica, no podrás volver a usarla hasta que termines un descanso largo, a menos que gastes 5 puntos de hechicería para usarla nuevamente.", effects = {} },
