        { id = "escarcha", name = "Escarcha", desc = "Control, ralentizacion y daño de hielo.", features = {
            { id = "mago_esc_truco", level = 2, name = "Truco adicional (moldear agua)", type = "informativo", description = "Aprendes moldear agua (u otro truco de mago); no cuenta en tu limite.", cantripSpellIds = { "moldear_agua" }, spellGrants = { { level = 0, ids = { "moldear_agua" } } }, effects = {} },
            { id = "mago_esc_dedos", level = 2, name = "Dedos de escarcha", type = "choice", companionId = "elemental_agua", description = "Elige Barrera de Hielo (escudo de PG temporal con conjuros de frío) o Elemental de Agua (compañero).", effects = {}, choice = {
                slots = 1,
                options = {
                    { id = "barrera", icon = "spell_ice_lament", label = "Barrera de Hielo", desc = "Al lanzar un conjuro de nivel 1 o superior que inflija dano por frio, deformas parte de su magia para crear una barrera de hielo que dura hasta que termines un descanso largo. Tiene puntos de golpe iguales al DOBLE de tu nivel de mago mas tu Mod. Inteligencia y absorbe el dano en tu lugar. Cada vez que lances un conjuro de nivel 1 o superior que cause dano por frio, la barrera recupera puntos de golpe iguales al doble del nivel del conjuro. Al reducirse a 0, cada criatura a 3 metros ve reducida su velocidad en 3 metros hasta el inicio de tu proximo turno al estallar.", effects = {} },
                    { id = "elemental", label = "Elemental de Agua", icon = "spell_frost_summonwaterelemental_2", desc = "Aprendes a conjurar un elemental de agua. Es amistoso contigo y tus companeros y obedece tus ordenes. Comparte tu cuenta de iniciativa pero toma su turno inmediatamente despues del tuyo. Puede moverse y usar su reaccion por si solo, pero la unica accion que toma en su turno es la de Esquivar, a menos que uses tu accion adicional para ordenarle otra. Si le lanzas un conjuro de frio, es inmune y recupera puntos de golpe iguales al dano infligido.", effects = {} },
                },
            } },
            { id = "mago_esc_congelacion", level = 6, name = "Congelacion cerebral", cast = "ninguna", type = "accion", resourceKey = "mage_point", resourceCost = 1, dcAbility = "Inteligencia", area = { shape = "other", sizeText = "Objetivo", resolution = "save", saveAbility = "Fuerza", success = "none", conditionId = "restrained", conditionDuration = "rounds", conditionTurns = 10 }, description = "El daño por frío de tus conjuros reduce 10 pies la velocidad; puedes gastar un punto de hechicería para restringir (salvación de Fuerza).", effects = {} },
            { id = "mago_esc_manos_de_escarcha", icon = "spell_frost_frostshock", level = 10, name = "Manos de Escarcha", type = "informativo", description = "Obtienes una de las siguientes características, dependiendo de tu elección a nivel 2.\n\n***Barrera de hielo.*** Cuando una criatura que puedes ver dentro de 9 metros de ti recibe daño, puedes usar tu reacción para hacer que tu Barrera de Hielo se manifieste alrededor de ella y absorba el daño. Si este daño reduce la barrera a 0 puntos de golpe, la criatura barricada recibe cualquier daño restante.\n\nAdemás, ahora puedes gastar puntos de hechicería para causar el efecto de Congelación Cerebral.\n\n***Elemental de agua.*** Tu elemental de agua se convierte en un elemental de hielo y obtiene los siguientes beneficios adicionales:\n\n• Gana inmunidad al daño por frío. • Congelación Cerebral ahora se aplica al daño por frío causado por el elemental. • Puede lanzar el conjuro *tormenta de hielo* una vez por descanso largo, usando tu CD de salvación de conjuros (requiere tu acción adicional).", effects = {} },
            { id = "mago_esc_anillo_de_escarcha", icon = "spell_frost_frostnova", level = 14, name = "Anillo de Escarcha", type = "informativo", description = "Puedes usar tu acción para conjurar un anillo de runas mágicas que invoca el frío más profundo alrededor de un punto que elijas dentro de 18 metros. El anillo tiene un radio de 9 metros y llena un cilindro de 3 metros de altura con frío gélido.\n\nLas criaturas dentro del área deben tener éxito en una tirada de salvación de Fuerza contra la CD de salvación de tus conjuros o quedar paralizadas hasta 1 minuto o hasta que reciban daño. Si el cuerpo de una criatura está completamente dentro del área, la tirada de salvación se realiza con desventaja. En una tirada de salvación exitosa, la criatura no queda restringida.\n\nAdemás, las criaturas que pasan por el área por medios no mágicos tienen su velocidad de movimiento reducida a la mitad hasta el final de su próximo turno después de salir del área. Además, los ataques a distancia realizados a través del área se hacen con desventaja.\n\nUna vez que uses esta característica, no podrás volver a usarla hasta que termines un descanso largo.\n\n___ *Impacto:* 1d8 + 2 + PB de daño contundente. *Impacto:* 1d6 + 2 + PB de daño por frío.", effects = {} },
        } },
