    features = {
        { id = "mago_lanzamiento_conjuros", level = 1, name = "Lanzamiento de conjuros", type = "pasivo", description = "Como estudiante de lo arcano, posees un libro de conjuros con hechizos que muestran los destellos de tu verdadero poder. Consulta [las reglas generales de lanzamiento de conjuros](reglas.html#conjuros); la lista de conjuros del mago está al final de esta ficha.\n\n### Trucos\nAl nivel 1, aprendes tres trucos de tu elección de la lista de conjuros de mago. Aprendes trucos adicionales de tu elección a niveles superiores, como se muestra en la columna de Conjuros Conocidos de la tabla de mago.\n\n### Libro de conjuros\nTienes un libro de conjuros que contiene seis conjuros de mago de 1er nivel de tu elección. Tu libro de conjuros no contiene tus trucos conocidos.\n\n### Preparar y lanzar conjuros\nLa tabla de mago muestra cuántos espacios de conjuro tienes para lanzar tus conjuros de 1er nivel o superior. Para lanzar uno de estos conjuros, debes gastar un espacio del nivel del conjuro o superior. Recuperas los espacios de conjuro gastados cuando terminas un descanso largo.\n\nPreparas la lista de conjuros de mago que están disponibles para ti. Para hacerlo, elige un número de conjuros de mago de tu libro de conjuros igual a Mod. Inteligencia + tu nivel de mago (mínimo de un conjuro). Los conjuros deben ser de un nivel para el que tengas espacios de conjuro.\n\nPor ejemplo, si eres un mago de 3er nivel, tienes cuatro espacios de conjuro de 1er nivel y dos de 2do nivel. Con una Inteligencia de 16, tu lista de conjuros preparados puede incluir seis conjuros de 1er o 2do nivel, en cualquier combinación, elegidos de tu libro de conjuros. Si preparas el conjuro de 1er nivel *proyectil mágico*, puedes lanzarlo usando un espacio de 1er o 2do nivel. Lanzar el conjuro no lo elimina de tu lista de preparados.\n\nPuedes cambiar tu lista de conjuros preparados cuando terminas un descanso largo. Preparar una nueva lista de conjuros de mago requiere tiempo dedicado a estudiar tu libro de conjuros y memorizar los encantamientos y gestos necesarios para lanzar el conjuro: 1 minuto por nivel del conjuro por cada conjuro en tu lista.\n\n### Habilidad para lanzar conjuros\nLa habilidad para lanzar tus conjuros de mago es la Inteligencia, ya que aprendes tus conjuros mediante el estudio y la memorización dedicados. Usas Mod. Inteligencia siempre que un conjuro haga referencia a tu habilidad para lanzar conjuros. Además, usas Mod. Inteligencia al establecer la CD de salvación para un conjuro de mago que lanzas y al hacer una tirada de ataque con uno.\n\n**CD de salvación de conjuros** = 8 + Bonus Competencia + Mod. Inteligencia\n\n**Modificador de ataque con conjuros** = Bonus Competencia + Mod. Inteligencia\n\n### Lanzamiento de rituales\nPuedes lanzar un conjuro de mago como un ritual si el conjuro tiene la etiqueta de ritual y está en tu libro de conjuros. No necesitas tener el conjuro preparado.\n\n### Foco para lanzar conjuros\nPuedes usar un foco arcano como foco para lanzar tus conjuros de mago.\n\n### Aprender hechizos\nCada vez que subes de nivel como mago, agregas dos conjuros de mago de tu elección a tu libro de conjuros. Cada uno de estos conjuros debe ser de un nivel para el que tengas espacios de conjuro, como se muestra en la tabla de mago. Durante tus aventuras, podrías encontrar otros conjuros que puedes agregar a tu libro de conjuros (consulta el recuadro \"Tu Libro de Conjuros\").", effects = {} },
        { id = "mago_sentido_magico", level = 1, name = "Sentido magico", type = "pasivo", description = "Tus estudios te enseñaron a percibir la energía mágica residual. Puedes sentir cuando un conjuro fue lanzado en el último hora en tu ubicación actual y ver escritura creada o usada por magia que esté oculta para otros. Mientras entiendas el idioma, también puedes descifrarla y leerla.", effects = {} },
        { id = "mago_fuente_magia", level = 2, name = "Fuente de magia", type = "pasivo", description = "Accedes a un profundo manantial de magia dentro de ti. Este manantial se representa mediante puntos de hechicería, que te permiten crear una variedad de efectos mágicos.\n\n### Puntos de hechicería\nTienes 2 puntos de hechicería y ganas más a medida que alcanzas niveles superiores, como se muestra en la columna de Puntos de Hechicería de la tabla de mago. Nunca puedes tener más puntos de hechicería que los mostrados en la tabla para tu nivel. Recuperas todos los puntos de hechicería gastados cuando terminas un descanso largo.\n\n### Lanzamiento flexible\nPuedes usar tus puntos de hechicería para ganar espacios de conjuro adicionales o sacrificar espacios de conjuro para ganar puntos de hechicería adicionales. Aprendes otras formas de usar tus puntos de hechicería a medida que alcanzas niveles superiores.\n\n***Creación de espacios de conjuro***\nPuedes transformar puntos de hechicería no gastados en un espacio de conjuro como una acción adicional en tu turno. Los espacios de conjuro creados desaparecen al final de un descanso largo. La tabla de Creación de Espacios de Conjuro muestra el coste de crear un espacio de conjuro de un nivel dado. No puedes crear espacios de conjuro de nivel superior a 5º.", effects = {
            { kind = "resourceMax", resource = "mage_point", perClassLevel = "mago", perLevel = 1 },
        } },
        { id = "mago_crear_espacio", level = 2, name = "Crear espacio de conjuro", cast = "accion_adicional", type = "accion", description = "Accion adicional: transformas puntos de hechiceria en un espacio de conjuro. Coste: 2 puntos para uno de 1.o, 3 para 2.o, 5 para 3.o, 6 para 4.o y 7 para 5.o. Los espacios creados desaparecen al terminar un descanso largo. No puedes crear espacios por encima del 5.o nivel.", actionKind = "slotConversion", slotConversion = { mode = "create", resource = "mage_point" }, effects = {} },
        { id = "mago_convertir_espacio", level = 2, name = "Convertir espacio en puntos", cast = "accion_adicional", type = "accion", description = "Accion adicional: gastas un espacio de conjuro y ganas puntos de hechiceria iguales al nivel del espacio.", actionKind = "slotConversion", slotConversion = { mode = "convert", resource = "mage_point" }, effects = {} },
        { id = "mago_estudio_magico", subclassMarker = true, level = 2, name = "Estudio magico", type = "informativo", description = "Eliges un estudio mágico que da forma a tu práctica de la magia a través de una de las tres áreas: Arcano, Fuego o Escarcha, detalladas al final de la descripción de la clase.\n\nTu elección te concede características a nivel 2 y de nuevo a los niveles 6, 10 y 14.", effects = {} },
        { id = "mago_metamagia", level = 3, name = "Metamagia", type = "choice", description = "Aprendes dos opciones de metamagia para alterar tus conjuros gastando puntos de hechicería (aprendes mas a niveles 10 y 17).", effects = {}, choice = {
            slots = 2,
            options = {
                { id = "cuidadoso", icon = "spell_arcane_arcaneresilience", label = "Conjuro Cuidadoso", resourceKey = "mage_point", resourceCost = 1, desc = "Al lanzar un conjuro que obliga a otras criaturas a una salvacion, gastas 1 punto de hechiceria y eliges un numero de esas criaturas igual a tu Mod. Inteligencia (minimo una): tienen exito automaticamente en su salvacion.", effects = {} },
                { id = "distante", icon = "spell_arcane_arcanepotency", label = "Conjuro Distante", resourceKey = "mage_point", resourceCost = 1, desc = "Al lanzar un conjuro con un alcance de 1,5 metros o mas, gastas 1 punto para duplicar su alcance. Si el alcance es de toque, pasa a 9 metros.", effects = {} },
                { id = "potenciado", icon = "spell_arcane_arcanepower", label = "Conjuro Potenciado", resourceKey = "mage_point", resourceCost = 1, desc = "Al tirar el dano de un conjuro, gastas 1 punto para repetir un numero de dados de dano igual a tu Mod. Inteligencia (minimo 1). Debes usar los nuevos resultados. Puedes usarlo aunque ya hayas usado otra metamagia en ese conjuro.", effects = {} },
                { id = "prolongado", icon = "spell_arcane_focusedpower", label = "Conjuro Prolongado", resourceKey = "mage_point", resourceCost = 1, desc = "Al lanzar un conjuro con duracion de 1 minuto o mas, gastas 1 punto para duplicar su duracion, hasta un maximo de 24 horas.", effects = {} },
                { id = "intensificado", icon = "spell_arcane_arcanetorrent", label = "Conjuro Intensificado", resourceKey = "mage_point", resourceCost = 3, desc = "Al lanzar un conjuro que obliga a una criatura a una salvacion para resistir sus efectos, gastas 3 puntos para dar a un objetivo desventaja en su PRIMERA salvacion contra el conjuro. En el manual aparece con el mismo nombre que Conjuro Potenciado.", effects = {} },
                { id = "rapido", icon = "spell_arcane_blink", label = "Conjuro Rapido", resourceKey = "mage_point", resourceCost = 2, desc = "Al lanzar un conjuro con tiempo de lanzamiento de 1 accion, gastas 2 puntos para cambiarlo a accion adicional en ese lanzamiento.", effects = {} },
                { id = "sutil", icon = "ability_mage_invisibility", label = "Conjuro Sutil", resourceKey = "mage_point", resourceCost = 1, desc = "Al lanzar un conjuro, gastas 1 punto para lanzarlo sin componentes somaticos ni verbales.", effects = {} },
                { id = "gemelo", icon = "spell_arcane_prismaticcloak", label = "Conjuro Gemelo (puntos = nivel del conjuro)", desc = "Al lanzar un conjuro de un solo objetivo y sin alcance personal, gastas puntos iguales al nivel del conjuro (1 si es un truco) para apuntar a una segunda criatura en el rango. El conjuro no debe ser capaz de apuntar a mas de una criatura a su nivel actual.", effects = {} },
            },
        } },
        { id = "mago_formulas_cantrips", level = 3, name = "Formulas de trucos", type = "pasivo", description = "Has escrito un conjunto de fórmulas arcanas en tu libro de conjuros que puedes usar para formular un truco en tu mente. Cada vez que termines un descanso largo y consultes esas fórmulas en tu libro de conjuros, puedes reemplazar un truco de mago que conozcas por otro truco de la lista de conjuros del mago.", effects = {} },
